export function redirectResponse(request){
 if(!['GET','HEAD'].includes(request.method))return null;
 const url=new URL(request.url),path=url.pathname.replace(/\/index\.html$/,'/').replace(/\/?$/,'/');
 if(!Object.hasOwn(redirects,path))return null;
 const target=new URL(redirects[path],url);
 if(!target.search)target.search=url.search;
 return new Response(null,{status:301,headers:{Location:target.pathname+target.search+target.hash}});
}
export default {fetch(request,env){return redirectResponse(request)||env.ASSETS.fetch(request);}};
